-- Nexus v3360.0 — validated metropolitan delta and fail-closed CJ policy layer.
--
-- 853 logical PDF rows were parsed; 37 US/GB destinations already exist in
-- v3340 and are intentionally not duplicated. This migration adds 816 rows.
-- All 853 names were cross-checked against GeoNames; Anápolis/GO, Huanggang,
-- Japanese prefectures, aliases, duplicate Noida, homonymous US cities, one
-- Moscow district, one Chinese county, and the two Crimean rows have safe
-- handling in the external evidence bundle.
--
-- No referral URL, CJ token, publisher CID/PID, click, impression, conversion,
-- price, EPC or sales claim is versioned here. The optional transaction-local
-- nexus.v3360_cj_links_json payload may install individually encrypted CJ URLs
-- after a fresh read-only API revalidation. Without that payload every route is
-- disabled and resolves as "Sintonizado em Análise".
begin;
set local statement_timeout='4000ms';
set local lock_timeout='1000ms';
set local idle_in_transaction_session_timeout='15000ms';

create temporary table nexus_v3360_catalog_baseline on commit drop as
select (select count(*) from public.ads) ads_rows,
       (select count(*) from public.ads where active) active_ads_rows,
       (select count(*) from public.nexus_v370_keyword_source) keyword_rows,
       (select count(*) from public.nexus_v380_keyword_vectors) vector_rows;

create or replace function public.nexus_v3360_norm(p_value text)
returns text language sql immutable strict parallel safe
as $function$
 select btrim(regexp_replace(
   translate(lower(normalize(p_value,NFKC)),
     'áàâãäåéèêëíìîïóòôõöúùûüçñýÿæœÁÀÂÃÄÅÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇÑÝŸÆŒ’',
     'aaaaaaeeeeiiiiooooouuuucnyyaoAAAAAAEEEEIIIIOOOOOUUUUCNYYAO '),
   '[^[:alnum:]]+',' ','g'));
$function$;

create table if not exists public.nexus_v3360_city_delta (
 city_id bigint generated always as identity primary key,
 source_country_code text not null,
 routing_country_code text not null,
 primary_locale text not null,
 locale_codes text[] not null,
 admin_area text not null,
 validated_admin_area text,
 destination_name text not null,
 destination_key text generated always as(public.nexus_v3360_norm(destination_name)) stored,
 aliases text[] not null,
 destination_type text not null,
 source_ordinal integer not null,
 source_document text not null,
 source_sha256 text not null,
 source_claim_scope text not null,
 geonames_id bigint not null,
 geonames_feature_code text not null,
 geonames_modified date not null,
 routing_eligible boolean not null,
 city_only_routing_eligible boolean not null,
 admin_required_for_disambiguation boolean not null,
 review_note text,
 installed_by_release text not null,
 created_at timestamptz not null default clock_timestamp(),
 updated_at timestamptz not null default clock_timestamp(),
 constraint nexus_v3360_source_cc_ck check(source_country_code in('US','CN','RU','DE','BR','GB','JP','IN')),
 constraint nexus_v3360_route_cc_ck check(routing_country_code in('US','CN','HK','MO','RU','UA','DE','BR','GB','JP','IN')),
 constraint nexus_v3360_locale_ck check(primary_locale=any(locale_codes)),
 constraint nexus_v3360_type_ck check(destination_type in('city','administrative_area')),
 constraint nexus_v3360_source_scope_ck check(source_claim_scope='operator_reference_crosschecked_geonames'),
 constraint nexus_v3360_sha_ck check(source_sha256~'^[a-f0-9]{64}$'),
 constraint nexus_v3360_release_ck check(installed_by_release='v3360.0'),
 constraint nexus_v3360_source_row_uq unique(source_document,source_ordinal),
 constraint nexus_v3360_route_admin_city_uq unique(routing_country_code,admin_area,destination_key)
);
revoke all on table public.nexus_v3360_city_delta from public,anon,authenticated,service_role;
revoke all on sequence public.nexus_v3360_city_delta_city_id_seq from public,anon,authenticated,service_role;

