create table if not exists public.nexus_v3360_cj_placement_policy (
 placement_key text primary key,
 advertiser_id text not null,
 advertiser_name text not null,
 link_id text not null,
 link_name text not null,
 country_code text not null,
 locale text not null,
 intent text not null,
 category text not null,
 link_language text not null,
 link_type text not null,
 promotion_type text not null,
 promotion_start_at timestamp,
 promotion_end_at timestamp,
 coupon_present boolean not null,
 mobile_optimized boolean not null,
 cross_device_only boolean not null,
 mobile_tracking_certified boolean not null,
 cookieless_tracking_enabled boolean not null,
 account_status text not null,
 relationship_status text not null,
 terms_status text not null,
 terms_end_at timestamptz,
 pid_generated_link boolean not null,
 target_country_verified boolean not null,
 evidence_observed_at timestamptz not null,
 evidence_expires_at timestamptz not null,
 affiliate_url_enc bytea,
 affiliate_host_sha256 text,
 route_enabled boolean not null default false,
 activation_reason text not null,
 installed_by_release text not null,
 created_at timestamptz not null default clock_timestamp(),
 updated_at timestamptz not null default clock_timestamp(),
 constraint nexus_v3360_cj_country_ck check(country_code in('US','CN','RU','DE','BR','GB','JP','IN')),
 constraint nexus_v3360_cj_intent_ck check(intent in('travel','flight','hotel','vacation','car_rental','wellness_travel')),
 constraint nexus_v3360_cj_link_type_ck check(link_type='Text Link'),
 constraint nexus_v3360_cj_status_ck check(account_status='Active' and relationship_status='joined' and terms_status='ACTIVE'),
 constraint nexus_v3360_cj_release_ck check(installed_by_release='v3360.0'),
 constraint nexus_v3360_cj_route_ck check(not route_enabled or (
  affiliate_url_enc is not null and octet_length(affiliate_url_enc)>32 and pid_generated_link and
  target_country_verified and account_status='Active' and relationship_status='joined' and terms_status='ACTIVE')),
 constraint nexus_v3360_cj_country_link_uq unique(country_code,advertiser_id,link_id)
);
