set search_path='public','extensions','pg_temp'
as $function$
declare v_kms text;v_url text;v_host text;v_seen integer:=0;r record;
begin
 perform set_config('statement_timeout','3000',true);perform set_config('lock_timeout','1000',true);
 begin
  if p_payload is null or jsonb_typeof(p_payload)<>'object' or jsonb_typeof(p_payload->'rows')<>'array'
     or jsonb_array_length(p_payload->'rows')<>87
     or (select count(distinct x->>'placement_key') from jsonb_array_elements(p_payload->'rows')x)<>87
  then raise exception 'v3360 CJ hydration payload invalid';end if;
  select value into strict v_kms from public.nexus_growth_secrets where key='nexus_satellites_kms';
  if length(btrim(v_kms))<16 then raise exception 'v3360 KMS unavailable';end if;
  for r in select * from jsonb_to_recordset(p_payload->'rows') as x(
   placement_key text,affiliate_url text,observed_at timestamptz,account_active boolean,
   relationship_joined boolean,terms_active boolean,pid_generated boolean,target_country_match boolean)
  loop
   v_url:=nullif(btrim(r.affiliate_url),'');v_host:=lower(substring(v_url from '^https://([^/:?#]+)'));
   if v_url is null or v_host is null
      or v_host<>all(array['www.anrdoezrs.net','www.dpbolvw.net','www.jdoqocy.com','www.kqzyfj.com','www.tkqlhce.com'])
      or v_url!~'^https://www\.(anrdoezrs\.net|dpbolvw\.net|jdoqocy\.com|kqzyfj\.com|tkqlhce\.com)/click-[0-9]+-[0-9]+'
      or r.observed_at<clock_timestamp()-interval '24 hours' or r.observed_at>clock_timestamp()+interval '5 minutes'
      or not coalesce(r.account_active,false) or not coalesce(r.relationship_joined,false)
      or not coalesce(r.terms_active,false) or not coalesce(r.pid_generated,false)
      or not coalesce(r.target_country_match,false) then raise exception 'v3360 CJ row failed validation';end if;
   update public.nexus_v3360_cj_placement_policy set
    affiliate_url_enc=extensions.pgp_sym_encrypt(v_url,v_kms,'cipher-algo=aes256,compress-algo=1'),
    affiliate_host_sha256=encode(extensions.digest(v_host,'sha256'),'hex'),
    evidence_observed_at=r.observed_at,evidence_expires_at=r.observed_at+interval '24 hours',
    route_enabled=true,activation_reason='fresh_encrypted_cj_link_installed',updated_at=clock_timestamp()
   where placement_key=r.placement_key;
   if not found then raise exception 'v3360 unknown placement key';end if;
   v_seen:=v_seen+1;v_url:=null;v_host:=null;
  end loop;
  if v_seen<>87 or (select count(*) from public.nexus_v3360_cj_placement_policy where route_enabled and affiliate_url_enc is not null)<>87 then raise exception 'v3360 CJ hydration count failed';end if;
  insert into public.nexus_v3000_capability_registry(capability,enabled,evidence,checked_at) values
   ('v3360_cj_routes',true,jsonb_build_object('enabled_routes',87,'fresh_encrypted_payload',true,'plaintext_returned',false),clock_timestamp())
  on conflict(capability) do update set enabled=excluded.enabled,evidence=excluded.evidence,checked_at=excluded.checked_at;
  v_kms:=null;v_url:=null;v_host:=null;p_payload:=null;
  return jsonb_build_object('version','v3360.0','installed',87,'encrypted',true,'plaintext_returned',false);
 exception when others then v_kms:=null;v_url:=null;v_host:=null;p_payload:=null;raise;end;
end
$function$;
revoke all on function public.nexus_v3360_hydrate_cj(jsonb) from public,anon,authenticated,service_role;
grant execute on function public.nexus_v3360_hydrate_cj(jsonb) to service_role;

-- Optional transaction-local deployment path retained for direct database
-- sessions; production automation uses the prepared PostgREST RPC above.
do $hydrate_from_guc$
declare v_payload jsonb;
begin
 begin
  v_payload:=nullif(current_setting('nexus.v3360_cj_links_json',true),'')::jsonb;
  if v_payload is not null then perform public.nexus_v3360_hydrate_cj(v_payload);end if;
  perform set_config('nexus.v3360_cj_links_json','',true);v_payload:=null;
 exception when others then perform set_config('nexus.v3360_cj_links_json','',true);v_payload:=null;raise;end;
end
$hydrate_from_guc$;

create or replace function public.nexus_v3360_resolve_city(
 p_headers jsonb,p_destination text,p_admin_area text,p_locale text,p_intent_text text,p_user_supplied_destination boolean
) returns jsonb language plpgsql security definer
set search_path='public','extensions','pg_temp'
as $function$
declare v_country text;v_geo_source text;v_key text;v_admin_key text;v_intent_text text;v_intent text;v_count integer;v_copy text;r public.nexus_v3360_city_delta%rowtype;p public.nexus_v3360_cj_placement_policy%rowtype;
begin
 perform set_config('statement_timeout','2000',true);perform set_config('lock_timeout','1000',true);
 begin
  if p_headers is null or jsonb_typeof(p_headers)<>'object' or p_user_supplied_destination is not true then
   return jsonb_build_object('version','v3360.0','estado','Sintonizado em Análise','motivo','trusted_user_query_context_required','affiliate_url',null);
  end if;
  select upper(btrim(e.value)),lower(e.key) into v_country,v_geo_source from jsonb_each_text(p_headers)e
   where lower(e.key) in('cf-ipcountry','x-vercel-ip-country') and btrim(e.value)<>''
   order by case lower(e.key) when 'cf-ipcountry' then 0 else 1 end,lower(e.key),e.key,e.value limit 1;
  if v_country is null or v_country!~'^[A-Z]{2}$' or v_country in('XX','T1') then
   return jsonb_build_object('version','v3360.0','estado','Sintonizado em Análise','motivo','cdn_country_unavailable','affiliate_url',null,'human_or_residential_proven',false);
  end if;
  if p_destination is null or length(btrim(p_destination)) not between 2 and 120
     or p_intent_text is null or length(btrim(p_intent_text)) not between 3 and 500 then
   return jsonb_build_object('version','v3360.0','estado','Sintonizado em Análise','motivo','payload_invalid','affiliate_url',null);
  end if;
  v_key:=public.nexus_v3360_norm(p_destination);v_admin_key:=public.nexus_v3360_norm(coalesce(p_admin_area,''));v_intent_text:=public.nexus_v3360_norm(p_intent_text);
  select count(*) into v_count from public.nexus_v3360_city_delta c where c.routing_country_code=v_country
    and (c.destination_key=v_key or exists(select 1 from unnest(c.aliases)a where public.nexus_v3360_norm(a)=v_key))
    and (v_admin_key='' or public.nexus_v3360_norm(c.admin_area)=v_admin_key or public.nexus_v3360_norm(coalesce(c.validated_admin_area,''))=v_admin_key);
  if v_count=0 then return jsonb_build_object('version','v3360.0','estado','Sintonizado em Análise','motivo','destination_not_in_v3360_delta','country',v_country,'affiliate_url',null);end if;
  if v_count>1 then return jsonb_build_object('version','v3360.0','estado','Sintonizado em Análise','motivo','admin_area_required_for_ambiguous_destination','country',v_country,'matches',v_count,'affiliate_url',null);end if;
  select * into r from public.nexus_v3360_city_delta c where c.routing_country_code=v_country
    and (c.destination_key=v_key or exists(select 1 from unnest(c.aliases)a where public.nexus_v3360_norm(a)=v_key))
    and (v_admin_key='' or public.nexus_v3360_norm(c.admin_area)=v_admin_key or public.nexus_v3360_norm(coalesce(c.validated_admin_area,''))=v_admin_key) limit 1;
  if r.admin_required_for_disambiguation and v_admin_key='' then
   return jsonb_build_object('version','v3360.0','estado','Sintonizado em Análise','motivo','admin_area_required_for_ambiguous_destination','country',v_country,'destination',r.destination_name,'affiliate_url',null);
  end if;
  if not r.routing_eligible then
   return jsonb_build_object('version','v3360.0','estado','Sintonizado em Análise','motivo','destination_validated_but_routing_disabled','country',v_country,'destination',r.destination_name,'affiliate_url',null);
  end if;
  if p_locale is null or not exists(select 1 from unnest(r.locale_codes)l where lower(l)=lower(btrim(p_locale))) then
   return jsonb_build_object('version','v3360.0','estado','Sintonizado em Análise','motivo','locale_not_supported','country',v_country,'destination',r.destination_name,'supported_locales',r.locale_codes,'affiliate_url',null);
  end if;
  v_intent:=case
   when v_intent_text~'(^| )(hotel|hotels|hotelaria|酒店|ホテル|отель)( |$)' then 'hotel'
   when v_intent_text~'(^| )(flight|flights|voo|voos|flug|flüge|航班|航空券|рейс)( |$)' then 'flight'
   when v_intent_text~'(^| )(car rental|rent a car|aluguel de carro|mietwagen|租车|レンタカー|аренда автомобиля)( |$)' then 'car_rental'
   when v_intent_text~'(^| )(vacation|holiday|férias|urlaub|度假|休暇|отпуск)( |$)' then 'vacation'
   when v_intent_text~'(^| )(travel|trip|viagem|reise|旅行|путешествие)( |$)' then 'travel'
   else null end;
  if v_intent is null then return jsonb_build_object('version','v3360.0','estado','Sintonizado em Análise','motivo','travel_intent_not_explicit','country',v_country,'destination',r.destination_name,'affiliate_url',null);end if;
  select * into p from public.nexus_v3360_cj_placement_policy q where q.country_code=v_country and lower(q.locale)=lower(p_locale)
    and q.intent in(v_intent,'travel') and q.route_enabled and q.evidence_expires_at>clock_timestamp()
    and (q.promotion_start_at is null or q.promotion_start_at<=clock_timestamp()::timestamp)
    and (q.promotion_end_at is null or q.promotion_end_at>clock_timestamp()::timestamp)
    and (q.terms_end_at is null or q.terms_end_at>clock_timestamp())
   order by case when q.intent=v_intent then 0 else 1 end,q.placement_key limit 1;
  v_copy:=case split_part(lower(p_locale),'-',1)
   when 'pt' then 'Opções de viagem para quem pesquisa '||r.destination_name||'. Confirme disponibilidade, preço, cobertura do destino e condições no site do parceiro.'
   when 'es' then 'Opciones de viaje para quienes buscan '||r.destination_name||'. Confirma disponibilidad, precio, cobertura del destino y condiciones en el sitio del socio.'
   when 'de' then 'Reiseoptionen für die Suche nach '||r.destination_name||'. Verfügbarkeit, Preis, Zielabdeckung und Bedingungen sind auf der Partnerseite zu prüfen.'
   when 'zh' then '与'||r.destination_name||'搜索相关的旅行选项。请在合作伙伴网站上确认供应情况、价格、目的地覆盖范围和条款。'
   when 'ja' then r.destination_name||'を検索している方向けの旅行オプションです。空き状況、料金、対象地域、条件はパートナーサイトでご確認ください。'
   when 'ru' then 'Варианты путешествий для тех, кто ищет '||r.destination_name||'. Проверяйте наличие, цену, географию предложения и условия на сайте партнёра.'
   else 'Travel options for people researching '||r.destination_name||'. Confirm availability, price, destination coverage, and terms on the partner site.' end;
  return jsonb_build_object('version','v3360.0','estado',case when p.placement_key is null then 'Sintonizado em Análise' else 'ok' end,
   'motivo',case when p.placement_key is null then 'fresh_encrypted_affiliate_route_unavailable' else 'validated_internal_placement_available' end,
   'country',v_country,'geo_source',v_geo_source,'destination',r.destination_name,'admin_area',r.admin_area,
   'validated_admin_area',r.validated_admin_area,'locale',p_locale,'intent',v_intent,'content_copy',v_copy,
   'disclosure_required_before_link','#ad','disclosure_own_line',true,'placement_key',p.placement_key,
   'advertiser',p.advertiser_name,'link_name',p.link_name,'affiliate_url',null,'redirect_performed',false,
   'click_recorded',false,'city_availability_claimed',false,'country_target_match',coalesce(p.target_country_verified,false),
   'cdn_country_is_routing_hint',true,'city_inferred_from_cdn',false,'timezone_proven',false,
   'human_or_residential_proven',false,'buyer_intent_proven',false,'sales_claimed',false);
 exception when others then
  begin perform public.nexus_v420_sintonizado('v3360-city-resolver',coalesce(v_country,'unknown'),sqlstate||': '||left(sqlerrm,220));exception when others then null;end;
  return jsonb_build_object('version','v3360.0','estado','Sintonizado em Análise','motivo','resolver_error','affiliate_url',null);
 end;
end
$function$;
revoke all on function public.nexus_v3360_resolve_city(jsonb,text,text,text,text,boolean) from public,anon,authenticated,service_role;
grant execute on function public.nexus_v3360_resolve_city(jsonb,text,text,text,text,boolean) to service_role;

create or replace function public.nexus_v3360_operator_status() returns jsonb language plpgsql security definer
set search_path='public','cron','extensions','pg_temp' as $function$
begin
 perform set_config('statement_timeout','2000',true);
 return jsonb_build_object('version','v3360.0','observed_at',clock_timestamp(),
  'city_delta',jsonb_build_object('rows',(select count(*) from public.nexus_v3360_city_delta),
   'countries',(select jsonb_object_agg(source_country_code,n order by source_country_code) from (select source_country_code,count(*)n from public.nexus_v3360_city_delta group by source_country_code)x),
   'routing_eligible',(select count(*) from public.nexus_v3360_city_delta where routing_eligible),
   'city_only_ambiguous',(select count(*) from public.nexus_v3360_city_delta where admin_required_for_disambiguation),
   'all_geonames_crosschecked',(select bool_and(geonames_id>0) from public.nexus_v3360_city_delta)),
  'cj_policy',jsonb_build_object('rows',(select count(*) from public.nexus_v3360_cj_placement_policy),
   'enabled_routes',(select count(*) from public.nexus_v3360_cj_placement_policy where route_enabled and evidence_expires_at>clock_timestamp()),
   'encrypted_urls',(select count(*) from public.nexus_v3360_cj_placement_policy where affiliate_url_enc is not null),
   'plaintext_url_columns',0,'urls_returned',false),
  'publication',jsonb_build_object('city_pages_published',false,'seo_indexing_enabled',false,'redirect_endpoint_deployed',false),
  'protected_surfaces',jsonb_build_object('go_modified',false,'compose_modified',false,'programmatic_placements_modified',false),
  'claims',jsonb_build_object('clicks_performed',false,'impressions_created',false,'sales_claimed',false,'city_inferred_from_cdn',false,'country_header_proves_humanity',false));
exception when others then return jsonb_build_object('version','v3360.0','state','Sintonizado em Análise','observed_at',clock_timestamp());end
$function$;
revoke all on function public.nexus_v3360_operator_status() from public,anon,authenticated,service_role;
grant execute on function public.nexus_v3360_operator_status() to service_role;

insert into public.nexus_v3000_capability_registry(capability,enabled,evidence,checked_at) values
 ('v3360_city_delta',true,jsonb_build_object('rows',816,'source_rows',853,'v3340_overlap_not_duplicated',37,'all_rows_geonames_crosschecked',true),clock_timestamp()),
 ('v3360_cj_discovery',true,jsonb_build_object('joined_advertisers',223,'active_contracts_intersect_joined',223,'placement_policies',87,'affiliate_urls_versioned',false,'clicks_performed',false),clock_timestamp()),
 ('v3360_cj_routes',exists(select 1 from public.nexus_v3360_cj_placement_policy where route_enabled and evidence_expires_at>clock_timestamp()),jsonb_build_object('enabled_routes',(select count(*) from public.nexus_v3360_cj_placement_policy where route_enabled and evidence_expires_at>clock_timestamp()),'requires_fresh_encrypted_payload',true),clock_timestamp()),
 ('v3360_city_publication',false,jsonb_build_object('city_pages_published',false,'seo_indexing_enabled',false,'reason','unique useful landing content and fresh route evidence not physically validated'),clock_timestamp())
on conflict(capability) do update set enabled=excluded.enabled,evidence=excluded.evidence,checked_at=excluded.checked_at;

update public.nexus_v3200_copy_policies set active=true,directives=directives||jsonb_build_object(
 'activation_profile','v3360.0','deterministic_copy_remains_canonical',true,'city_availability_claim_allowed',false,
 'country_target_is_city_serviceability_proof',false,'disclosure_own_line_before_link',true,
 'city_page_programmatic_indexing_enabled',false,'affiliate_route_requires_fresh_encrypted_evidence',true,
 'cdn_country_is_human_proof',false,'fake_urgency_allowed',false,'fabricated_sales_allowed',false),checked_at=clock_timestamp()
where policy_version='v3200.0';

do $assert$
declare b record;s jsonb;persistence "char";
begin
 if (select count(*) from public.nexus_v3360_city_delta)<>816 then raise exception 'v3360 city delta count failed';end if;
 if (select jsonb_object_agg(source_country_code,n order by source_country_code) from (select source_country_code,count(*)n from public.nexus_v3360_city_delta group by source_country_code)x)
  <>jsonb_build_object('BR',50,'CN',115,'DE',92,'GB',39,'IN',74,'JP',50,'RU',127,'US',269) then raise exception 'v3360 country delta failed';end if;
 if (select count(*) from public.nexus_v3360_city_delta where routing_eligible)<>812 then raise exception 'v3360 routing eligibility failed';end if;
 if exists(select 1 from public.nexus_v3360_city_delta where geonames_id<=0) then raise exception 'v3360 crosscheck failed';end if;
 if (select count(*) from public.nexus_v3360_cj_placement_policy)<>87 then raise exception 'v3360 CJ policy count failed';end if;
 if exists(select 1 from information_schema.columns where table_schema='public' and table_name='nexus_v3360_cj_placement_policy' and column_name in('affiliate_url','click_url','tracking_url','pid','token')) then raise exception 'v3360 plaintext sensitive column failed';end if;
 select relpersistence into persistence from pg_class where oid='public.nexus_v3360_city_delta'::regclass;if persistence<>'p'::"char" then raise exception 'v3360 city table not LOGGED';end if;
 select relpersistence into persistence from pg_class where oid='public.nexus_v3360_cj_placement_policy'::regclass;if persistence<>'p'::"char" then raise exception 'v3360 policy table not LOGGED';end if;
 if has_table_privilege('anon','public.nexus_v3360_city_delta','select') or has_table_privilege('authenticated','public.nexus_v3360_city_delta','select') or has_table_privilege('service_role','public.nexus_v3360_city_delta','select') then raise exception 'v3360 city ACL failed';end if;
 if has_table_privilege('anon','public.nexus_v3360_cj_placement_policy','select') or has_table_privilege('authenticated','public.nexus_v3360_cj_placement_policy','select') or has_table_privilege('service_role','public.nexus_v3360_cj_placement_policy','select') then raise exception 'v3360 policy ACL failed';end if;
 if has_function_privilege('anon','public.nexus_v3360_resolve_city(jsonb,text,text,text,text,boolean)','execute') or has_function_privilege('authenticated','public.nexus_v3360_resolve_city(jsonb,text,text,text,text,boolean)','execute') or not has_function_privilege('service_role','public.nexus_v3360_resolve_city(jsonb,text,text,text,text,boolean)','execute') then raise exception 'v3360 resolver ACL failed';end if;
 select * into b from nexus_v3360_catalog_baseline;
 if b.ads_rows<>(select count(*) from public.ads) or b.active_ads_rows<>(select count(*) from public.ads where active) or b.keyword_rows<>(select count(*) from public.nexus_v370_keyword_source) or b.vector_rows<>(select count(*) from public.nexus_v380_keyword_vectors) then raise exception 'v3360 read-only catalog drift';end if;
 if not exists(select 1 from cron.job where jobid=60 and active and schedule='10 seconds') or exists(select 1 from cron.job where jobid in(15,16,64) and active) then raise exception 'v3360 protected jobs drift';end if;
 s:=public.nexus_v3360_operator_status();if (s#>>'{city_delta,rows}')::integer<>816 or (s#>>'{cj_policy,rows}')::integer<>87 then raise exception 'v3360 status failed';end if;
end
$assert$;
commit;
